import { defineExperience, startExperience } from '@signal-lab/experience-sdk';
import { LanternScene } from './scene';
import { direct, type DirectedState } from './director';

let scene: LanternScene | null = null;
let root: HTMLElement | null = null;
let cleanups: Array<() => void> = [];
let lastState: DirectedState | null = null;

function mount(context: Parameters<Parameters<typeof defineExperience>[0]['mount']>[0]): void {
  const { container, canvas, reducedMotion } = context;
  root = document.createElement('main');
  root.className = `lantern-page${reducedMotion ? ' is-reduced' : ''}`;
  root.innerHTML = `
    <div class="visual-wrap" data-signal-visual-anchor aria-hidden="true"></div>
    <header class="hero" id="start">
      <p class="eyebrow">FIELD NOTE 04 · 可折叠日光露营灯</p>
      <h1>把一盏日光，<br>收进背包侧袋。</h1>
      <p class="lead">向下滚动，亲眼看它从扁平收纳展开成稳定、温暖的营地照明。</p>
      <nav class="state-nav" aria-label="查看灯具状态">
        <button data-stop="0">收纳</button><button data-stop="0.34">半展开</button><button data-stop="0.68">完全展开</button><button data-stop="1">点亮</button>
      </nav>
      <a class="scroll-cue" href="#structure">查看折叠结构 ↓</a>
    </header>
    <section class="note note-a" id="structure">
      <p class="index">01 / PACK</p><h2>扁平时，给真正要带的装备让路。</h2>
      <p>灯罩沿纵向褶线收拢，提手与上下铝环保持完整；不拆零件，抵达营地后也无需重新组装。</p>
      <dl><div><dt>当前任务</dt><dd>展开灯罩</dd></div><div><dt>可见结果</dt><dd>照明体积由薄片恢复</dd></div></dl>
    </section>
    <section class="note note-b">
      <p class="index">02 / HINGE</p><h2>一拉展开，结构自己找到位置。</h2>
      <p>顶部提手抬升时，象牙色折叠灯罩逐层张开。固定的顶盖与底座让受力路径清楚，也让操作容易判断。</p>
    </section>
    <section class="note note-c">
      <p class="index">03 / USE</p><h2>完整展开，才是它真实工作的形态。</h2>
      <p>灯罩形成均匀的扩散面，宽底座稳定接地。白天看清结构，入夜后获得柔和而不刺眼的近场光。</p>
    </section>
    <section class="resolve" id="resolve">
      <div><p class="eyebrow">READY FOR CAMP</p><h2>为下一次露营<br>点亮它。</h2><p>从收纳到照明，只需一次连续展开。把可用的暖光，留给帐篷、晚餐和同行的人。</p><a class="cta" href="#start" data-action>选择这盏灯 <span>→</span></a></div>
    </section>`;
  container.appendChild(root);
  const visual = root.querySelector<HTMLElement>('.visual-wrap');
  if (!visual) return;
  scene = new LanternScene(visual, canvas);
  root.querySelectorAll<HTMLButtonElement>('[data-stop]').forEach((button) => {
    const handler = (): void => {
      const value = Number(button.dataset.stop ?? 0);
      const range = Math.max(1, document.documentElement.scrollHeight - innerHeight);
      scrollTo({ top: range * value, behavior: reducedMotion ? 'auto' : 'smooth' });
    };
    button.addEventListener('click', handler);
    cleanups.push(() => button.removeEventListener('click', handler));
  });
}

function update(frame: Parameters<Parameters<typeof defineExperience>[0]['update']>[0]): void {
  if (!scene || !root) return;
  lastState = direct(frame.progress, frame.pointer.x, frame.elapsed, frame.reducedMotion);
  scene.update(lastState);
  root.style.setProperty('--story', String(lastState.progress));
  root.querySelectorAll<HTMLButtonElement>('[data-stop]').forEach((button, index) => button.classList.toggle('active', index === lastState?.stage));
}

function resize(viewport: Parameters<Parameters<typeof defineExperience>[0]['resize']>[0]): void {
  scene?.resize(viewport.width, viewport.height, viewport.dpr);
}

function dispose(): void {
  cleanups.forEach((cleanup) => cleanup());
  cleanups = [];
  scene?.dispose();
  scene = null;
  root?.remove();
  root = null;
  lastState = null;
}

startExperience(defineExperience({ mount, update, resize, dispose }));

import type { DirectedState } from './director';

const SOURCE = '/creative-assets/r64-collapsible-lantern-four-state-v1.png';

export class LanternScene {
  private frames: HTMLElement[] = [];
  private glow: HTMLElement;
  private fallback: HTMLElement;
  private imageLoaded = false;
  private disposed = false;

  constructor(private host: HTMLElement, private canvas: HTMLCanvasElement) {
    this.canvas.classList.add('ambient-canvas');
    for (let index = 0; index < 4; index += 1) {
      const frame = document.createElement('div');
      frame.className = `product-frame frame-${index}`;
      frame.style.backgroundImage = `url(${SOURCE})`;
      this.host.appendChild(frame);
      this.frames.push(frame);
    }
    const probe = new Image();
    probe.src = SOURCE;
    probe.decoding = 'async';
    probe.addEventListener('load', () => { this.imageLoaded = true; this.host.classList.add('asset-ready'); }, { once: true });
    probe.addEventListener('error', () => this.host.classList.add('asset-failed'), { once: true });
    this.glow = document.createElement('div');
    this.glow.className = 'warm-field';
    this.host.appendChild(this.glow);
    this.fallback = document.createElement('div');
    this.fallback.className = 'lantern-fallback';
    this.fallback.innerHTML = '<span class="handle"></span><span class="shade"></span><span class="base"></span>';
    this.host.appendChild(this.fallback);
  }

  update(state: DirectedState): void {
    if (this.disposed) return;
    this.frames.forEach((frame, index) => {
      frame.style.opacity = String(state.weights[index]);
      frame.style.setProperty('--lift', `${state.lift[index]}px`);
    });
    this.glow.style.opacity = String(state.light);
    this.host.style.setProperty('--observe-x', `${state.observeX}px`);
    this.host.dataset.stage = String(state.stage);
    if (!this.imageLoaded) this.fallback.style.setProperty('--open', String(state.open));
  }

  resize(width: number, height: number, dpr: number): void {
    this.canvas.width = Math.max(1, Math.round(width * Math.min(dpr, 2)));
    this.canvas.height = Math.max(1, Math.round(height * Math.min(dpr, 2)));
  }

  dispose(): void {
    this.disposed = true;
    this.frames.forEach((frame) => frame.remove());
    this.glow.remove();
    this.fallback.remove();
    this.canvas.classList.remove('ambient-canvas');
    this.frames = [];
  }
}

export interface DirectedState {
  progress: number;
  stage: number;
  weights: [number, number, number, number];
  lift: [number, number, number, number];
  open: number;
  light: number;
  observeX: number;
}

const clamp = (value: number): number => Math.max(0, Math.min(1, value));
const smooth = (a: number, b: number, value: number): number => {
  const t = clamp((value - a) / (b - a));
  return t * t * (3 - 2 * t);
};

export function direct(progress: number, pointerX: number, elapsed: number, reducedMotion: boolean): DirectedState {
  const p = clamp(progress);
  const first = smooth(0.18, 0.38, p);
  const second = smooth(0.46, 0.7, p);
  const third = smooth(0.78, 0.94, p);
  const weights: [number, number, number, number] = [1 - first, first * (1 - second), second * (1 - third), third];
  // These thresholds follow the actual DOM section boundaries so the product
  // always occupies the side opposite the active editorial copy.
  const stage = p < 0.47 ? 0 : p < 0.64 ? 1 : p < 0.91 ? 2 : 3;
  const observation = reducedMotion ? 0 : (pointerX - 0.5) * 10;
  const settled = p > 0.96 || reducedMotion ? 0 : Math.sin(elapsed * 0.35) * 0.6;
  return {
    progress: p,
    stage,
    weights,
    lift: [0, -4 * first, -7 * second, -4 * third],
    open: 0.12 + first * 0.3 + second * 0.48 + third * 0.1,
    light: third,
    observeX: observation + settled
  };
}

*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:#d4ccbd;color:#223229;font-family:Arial,"Noto Sans SC",sans-serif;overflow-x:clip}
button,a{font:inherit}
.lantern-page{--ink:#223229;--paper:#ece7da;--orange:#b96525;position:relative;min-height:0;max-width:100%;isolation:isolate;background:#d4ccbd;overflow:clip}
.ambient-canvas{position:fixed;inset:0;width:100%;height:100%;z-index:-4;pointer-events:none}
.visual-wrap{position:fixed;inset:0;z-index:-3;overflow:hidden;background:radial-gradient(circle at 64% 48%,#eae4d8 0 18%,#d5ccbc 54%,#bcb3a3 100%)}
.visual-wrap:before{content:"";position:absolute;inset:-12%;background:radial-gradient(ellipse 34% 48% at 66% 52%,rgba(42,52,43,.22),transparent 68%),linear-gradient(90deg,rgba(233,228,215,.96) 0 26%,rgba(233,228,215,.42) 42%,transparent 63%);transition:background .65s ease;pointer-events:none}
.visual-wrap[data-stage="1"]:before,.visual-wrap[data-stage="3"]:before{background:radial-gradient(ellipse 34% 48% at 34% 52%,rgba(42,52,43,.22),transparent 68%),linear-gradient(270deg,rgba(233,228,215,.96) 0 26%,rgba(233,228,215,.42) 42%,transparent 63%)}
.visual-wrap:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(40,49,41,.18),transparent 32%),radial-gradient(circle at 50% 116%,rgba(72,78,66,.22),transparent 38%);pointer-events:none}
.product-frame{--product-x:66%;position:absolute;left:var(--product-x);top:50%;width:min(46vw,74vh);aspect-ratio:1;opacity:0;transform:translate3d(calc(-50% + var(--observe-x)),calc(-50% + var(--lift)),0);background-repeat:no-repeat;background-size:200.5% 200.5%;filter:saturate(.96) contrast(1.04) brightness(1.005) drop-shadow(0 30px 28px rgba(42,48,39,.28));-webkit-mask-image:radial-gradient(ellipse 62% 64% at 50% 52%,#000 64%,transparent 100%);mask-image:radial-gradient(ellipse 62% 64% at 50% 52%,#000 64%,transparent 100%);will-change:opacity,transform,left;transition:left .65s ease}
.frame-0{background-position:0 0}
.frame-1{background-position:100% 0}
.frame-2{background-position:0 100%}
.frame-3{background-position:100% 100%}
.visual-wrap[data-stage="1"] .product-frame,.visual-wrap[data-stage="3"] .product-frame{--product-x:34%}
.asset-ready .lantern-fallback{display:none}
.asset-failed .product-frame{display:none}
.warm-field{position:absolute;inset:0;opacity:0;background:radial-gradient(circle at 34% 51%,rgba(255,192,84,.42),rgba(255,218,148,.12) 24%,transparent 52%);mix-blend-mode:screen;pointer-events:none}
.lantern-fallback{--open:.12;position:absolute;left:63%;top:49%;width:min(25vw,260px);height:38vh;transform:translate(-50%,-50%);filter:drop-shadow(0 20px 18px rgba(53,59,44,.2))}
.handle{position:absolute;left:20%;top:0;width:60%;height:34%;border:8px solid #666d65;border-bottom:0;border-radius:80px 80px 0 0}
.shade{position:absolute;left:10%;bottom:14%;width:80%;height:calc(12% + var(--open)*52%);background:repeating-linear-gradient(90deg,#f4ecd7 0 12%,#d8c9ac 13% 15%);clip-path:polygon(8% 0,92% 0,100% 100%,0 100%)}
.base{position:absolute;left:4%;bottom:8%;width:92%;height:8%;border-radius:50%;background:#666d65}
.hero{min-height:100svh;width:min(610px,52vw);padding:8vh 0 8vh max(6vw,28px);display:flex;flex-direction:column;justify-content:center;align-items:flex-start;position:relative;z-index:1}
.eyebrow,.index{font:700 12px/1.4 ui-monospace,monospace;letter-spacing:.14em;color:#58685d}
.hero h1{margin:.14em 0 .28em;font:600 clamp(42px,5.4vw,74px)/1 Georgia,"Noto Serif SC",serif;letter-spacing:-.04em;max-width:9.4em}
.lead{max-width:29em;font-size:clamp(16px,1.3vw,19px);line-height:1.65}
.state-nav{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}
.state-nav button{border:1px solid rgba(34,50,41,.38);border-radius:99px;padding:9px 15px;background:rgba(245,241,231,.74);color:var(--ink);cursor:pointer}
.state-nav button.active{background:var(--ink);color:white}
.scroll-cue{color:var(--ink);text-underline-offset:5px}
.note{position:relative;z-index:1;min-height:82svh;width:min(450px,42vw);margin-left:6vw;padding:clamp(24px,4vw,46px);display:flex;flex-direction:column;justify-content:center;background:linear-gradient(90deg,rgba(236,231,218,.94),rgba(236,231,218,.76));border-left:1px solid rgba(34,50,41,.3);backdrop-filter:blur(10px)}
.note-b{margin-left:auto;margin-right:6vw;border-left:0;border-right:1px solid rgba(34,50,41,.3);background:linear-gradient(270deg,rgba(236,231,218,.94),rgba(236,231,218,.76))}
.note h2,.resolve h2{font:600 clamp(30px,3.5vw,50px)/1.1 Georgia,"Noto Serif SC",serif;letter-spacing:-.025em;margin:.2em 0}
.note p:not(.index),.resolve p{font-size:17px;line-height:1.72}
.note dl{display:flex;gap:28px;border-top:1px solid rgba(34,50,41,.3);padding-top:16px}
.note dt{font-size:12px;color:#657068}
.note dd{margin:5px 0;font-weight:700}
.resolve{position:relative;z-index:1;min-height:105svh;display:flex;align-items:center;padding:12vh 7vw}
.resolve>div{width:min(500px,45vw);margin-left:auto;padding:clamp(24px,4vw,46px);background:linear-gradient(270deg,rgba(236,231,218,.96),rgba(236,231,218,.78));border-right:1px solid rgba(34,50,41,.3);backdrop-filter:blur(10px)}
.resolve h2{font-size:clamp(40px,4.8vw,68px);max-width:8em}
.cta{display:inline-flex;gap:38px;align-items:center;margin-top:18px;padding:15px 20px;background:var(--orange);color:#fff;text-decoration:none;border-radius:3px;font-weight:700}
.cta span{font-size:23px}
.is-reduced .product-frame{transform:translate(-50%,-50%);transition:none}
.is-reduced .warm-field{transition:none}
@media(max-width:700px){
  .lantern-page{min-height:0}
  .visual-wrap{height:54vh;top:0;bottom:auto;background:radial-gradient(circle at 50% 42%,#ebe5d9 0 20%,#d4cbbb 64%,#bbb2a3 100%)}
  .visual-wrap:before,.visual-wrap[data-stage="1"]:before,.visual-wrap[data-stage="3"]:before{background:radial-gradient(ellipse 48% 54% at 50% 48%,rgba(42,52,43,.2),transparent 70%)}
  .product-frame,.visual-wrap[data-stage="1"] .product-frame,.visual-wrap[data-stage="3"] .product-frame{--product-x:50%;top:47%;width:min(92vw,52vh)}
  .warm-field{background:radial-gradient(circle at 50% 42%,rgba(255,192,84,.42),transparent 55%)}
  .hero{min-height:100svh;width:100%;padding:56vh 22px 36px;justify-content:flex-start}
  .hero h1{font-size:clamp(38px,11.5vw,56px);max-width:8em}
  .lead{font-size:16px}
  .state-nav{gap:6px;margin:12px 0}
  .state-nav button{padding:8px 11px}
  .note,.note-b{min-height:96svh;width:auto;margin:0;padding:58vh 22px 8vh;justify-content:flex-start;background:linear-gradient(0deg,#ece7da 0 42%,rgba(236,231,218,.86) 56%,transparent 70%);border:0;backdrop-filter:none}
  .note h2{font-size:clamp(30px,8.8vw,42px)}
  .resolve{min-height:105svh;padding:57vh 22px 8vh;align-items:flex-start;background:linear-gradient(0deg,#ece7da 0 42%,rgba(236,231,218,.86) 57%,transparent 72%)}
  .resolve>div{width:100%;margin:0;padding:0;background:none;border:0;backdrop-filter:none}
  .resolve h2{font-size:clamp(38px,11.5vw,54px);max-width:8em}
  .lantern-fallback{left:50%;top:44%;width:42vw;height:32vh}
}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
